import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string; message:string}[]): void {
  const detail: Record<string, unknown> = { code, message };
  if (fields) detail.fields = fields;
  send(res, status, { error: detail });
}
function methodNotAllowed(res: ServerResponse): void { error(res, 405, 'method_not_allowed', 'Method not allowed.'); }
function notFound(res: ServerResponse): void { error(res, 404, 'not_found', 'Resource not found.'); }

async function readBody(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let length = 0;
  for await (const part of req) {
    const chunk = Buffer.isBuffer(part) ? part : Buffer.from(part);
    length += chunk.length;
    if (length > 100_000) throw new Error('body-too-large');
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown;
}

function createJob(input: string, steps: number, failAttempts: number, key: string | null) {
  const payload = JSON.stringify({ input, steps, failAttempts });
  const now = new Date().toISOString();
  const id = randomUUID();
  db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,idempotency_key,payload,available_at)
    VALUES(?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, 0)`).run(id, input, steps, failAttempts, now, now, key, payload);
  return toJob(db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as Record<string, unknown>);
}

const server = createServer((req, res) => {
  void handle(req, res).catch(() => {
    if (!res.headersSent) error(res, 500, 'internal_error', 'An internal error occurred.');
    else res.destroy();
  });
});

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/health') {
    if (req.method !== 'GET') return methodNotAllowed(res);
    const heartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - Number(heartbeat.seen_at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (req.method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (req.method !== 'POST') return methodNotAllowed(res);
    const fields: {field:string; message:string}[] = [];
    if (!/^application\/json(?:\s*;|\s*$)/i.test(req.headers['content-type'] ?? '')) fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    let body: unknown;
    try { body = await readBody(req); } catch { fields.push({ field: 'body', message: 'Body must be valid JSON.' }); }
    const keyHeader = req.headers['idempotency-key'];
    const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
    let input: unknown, steps: unknown = 5, failAttempts: unknown = 0;
    if (body === null || typeof body !== 'object' || Array.isArray(body)) fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    else {
      const obj = body as Record<string, unknown>;
      for (const name of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(name)) fields.push({ field: name, message: 'Unknown field.' });
      input = obj.input; steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5; failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
      if (typeof input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
      else if (input.length < 1 || input.length > 1000 || !input.trim()) fields.push({ field: 'input', message: 'Must be 1–1000 characters and not only whitespace.' });
      if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
      if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    }
    if (fields.length) {
      const grouped = new Map<string, string[]>();
      for (const field of fields) grouped.set(field.field, [...(grouped.get(field.field) ?? []), field.message]);
      return error(res, 400, 'invalid_request', 'Request validation failed.', [...grouped].map(([field, messages]) => ({ field, message: [...new Set(messages)].join(' ') })));
    }
    const normalized = JSON.stringify({ input, steps, failAttempts });
    if (key) {
      db.exec('BEGIN IMMEDIATE');
      try {
        const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as Record<string, unknown> | undefined;
        if (existing) {
          db.exec('COMMIT');
          if (String(existing.payload) !== normalized) return error(res, 409, 'idempotency_conflict', 'This key was already used with a different payload.');
          return send(res, 200, toJob(existing));
        }
        const job = createJob(input as string, steps as number, failAttempts as number, key);
        db.exec('COMMIT'); return send(res, 201, job);
      } catch (e) { db.exec('ROLLBACK'); throw e; }
    }
    return send(res, 201, createJob(input as string, steps as number, failAttempts as number, null));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return methodNotAllowed(res);
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return notFound(res); }
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as Record<string, unknown> | undefined;
    return row ? send(res, 200, toJob(row)) : notFound(res);
  }
  notFound(res);
}

server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);

